CREATE OR REPLACE FUNCTION public.icash_opportunity_score(p_account uuid, p_result jsonb, p_zip text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare base numeric;prediction double precision;
begin
 base:=public.icash_opportunity_score_before_ranker(p_account,p_result,p_zip);
 if p_result->'financialCheck'->>'status' is distinct from 'eligible' then return base;end if;
 select a.prediction into prediction from icash_ranker_private.samples a
 join icash_ranker_private.settings s on s.id=1 and s.enabled and s.active_model is not null
 join icash_ranker_private.runs r on r.id=a.model_id and r.status='qualified' and r.created_at>now()-interval '7 days'
 where a.account_id=p_account and a.property_key=md5(p_result->'property'->>'propertyId') and a.cohort='learned';
 return case when prediction is null then base else 0.85*base+0.15*prediction::numeric end;
end $function$

CREATE OR REPLACE FUNCTION public.icash_opportunity_market_score_before_demand(p_account uuid, p_zip text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare s jsonb;
begin
 s:=public.icash_shared_learning_stats('market','research-v1',p_zip)->0;
 if coalesce((s->>'contributors')::integer,0)<3 or coalesce((s->>'effective_attempts')::numeric,0)<60 then return public.icash_opportunity_market_score_local(p_account,p_zip);end if;
 return greatest(-0.5,least(1,0.7*public.icash_learning_lower((s->>'effective_positive')::numeric,(s->>'effective_attempts')::numeric)
  +0.3*public.icash_learning_lower((s->>'effective_contracts')::numeric,(s->>'effective_contract_trials')::numeric)
  -least(0.5,(s->>'effective_opted_out')::numeric/greatest(1,(s->>'effective_attempts')::numeric))));
end $function$
